using Microsoft.AspNetCore.Authentication.Certificate;
using Microsoft.AspNetCore.Server.Kestrel.Https;
using System.Security.Claims;
using System.Security.Cryptography.X509Certificates;

var builder = WebApplication.CreateBuilder(args);

// Certs are generated by scripts/generate-certs.ps1 and copied to output (Resources/Certificates).
// Server keeps only public material (.crt): public key + metadata, no private key, no password.
// - ca.crt: trust anchor — the whole client certificate chain must chain to this CA (Certificate Authority).
// - client-*.crt: allowlist of accepted clients. Project policy: thumbprint match.
//   After a match, identity (CN / clientId, …) is taken from the presented client cert.

var certsDir = Path.Combine(AppContext.BaseDirectory, "Resources", "Certificates");

var caPath = Path.Combine(certsDir, "ca.crt");
if (!File.Exists(caPath))
{
    throw new InvalidOperationException(
        "Demo CA certificate is missing in configuration. Run .\\scripts\\generate-certs.ps1 first " +
        $"(expected: {caPath}).");
}

var configuredCACert = X509CertificateLoader.LoadCertificateFromFile(caPath);

if (configuredCACert.NotAfter < DateTimeOffset.UtcNow)
{
    throw new InvalidOperationException(
        "Demo CA certificate in configuration has expired. Run .\\scripts\\generate-certs.ps1 to regenerate the certs.");
}

var trustedConfiguredClientCertificatesThumbprints = Directory.GetFiles(certsDir, "client-*.crt")
    .Select(X509CertificateLoader.LoadCertificateFromFile)
    .Select(c => c.Thumbprint)
    .ToHashSet(StringComparer.OrdinalIgnoreCase);

if (trustedConfiguredClientCertificatesThumbprints.Count == 0)
{
    throw new InvalidOperationException(
        "No trusted client certificates thumbprints were found in configuration. Run .\\scripts\\generate-certs.ps1 first " +
        $"(expected: {certsDir}\\client-*.crt).");
}

builder.WebHost.ConfigureKestrel(options =>
{
    options.ConfigureHttpsDefaults(httpsOptions =>
    {
        // Require client certificate for all HTTPS endpoints in the API (mTLS).
        // This ignores [Authorize] attributes on endpoints:
        // Kestrel will reject the connection if the client doesn't present a valid certificate.
        httpsOptions.ClientCertificateMode = ClientCertificateMode.RequireCertificate;

        // TLS gate: thumbprint allowlist + chain → demo CA.
        httpsOptions.ClientCertificateValidation = (certificateFromRequest, _, _) =>
        {
            if (certificateFromRequest is null)
            {
                return false;
            }

            if (certificateFromRequest is not X509Certificate2 clientCertFromRequest)
            {
                clientCertFromRequest = X509CertificateLoader.LoadCertificate(certificateFromRequest.GetRawCertData());
            }

            // Validate the client certificate against whitelist of thumbprints (trusted client certs).
            if (!trustedConfiguredClientCertificatesThumbprints.Contains(clientCertFromRequest.Thumbprint))
            {
                return false;
            }

            // Validate the client certificate chain against the demo CA (trust anchor).
            using var chain = new X509Chain();
            chain.ChainPolicy.TrustMode = X509ChainTrustMode.CustomRootTrust;
            chain.ChainPolicy.CustomTrustStore.Add(configuredCACert);
            chain.ChainPolicy.RevocationMode = X509RevocationMode.NoCheck;

            return chain.Build(clientCertFromRequest);
        };
    });
});

// Map the client certificate into ASP.NET identity (HttpContext.User / claims)
// so endpoints can read clientId, thumbprint, etc. from the request context.
builder.Services
    .AddAuthentication(CertificateAuthenticationDefaults.AuthenticationScheme)
    .AddCertificate(options =>
    {
        options.AllowedCertificateTypes = CertificateTypes.All;
        options.RevocationMode = X509RevocationMode.NoCheck;
        // Handler still needs our CA in its trust store to accept the cert when building the principal
        // (it re-checks chain internally; the real connection gate is Kestrel above).
        options.ChainTrustValidationMode = X509ChainTrustMode.CustomRootTrust;
        options.CustomTrustStore.Add(configuredCACert);

        options.Events = new CertificateAuthenticationEvents
        {
            OnCertificateValidated = context =>
            {
                var cert = context.ClientCertificate;

                // Identity comes from the presented cert after TLS already allowed it.
                var clientId = cert.GetNameInfo(X509NameType.SimpleName, forIssuer: false);
                if (string.IsNullOrWhiteSpace(clientId))
                {
                    context.Fail("Client certificate has no CN / simple name.");
                    return Task.CompletedTask;
                }

                var claims = new[]
                {
                    new Claim(ClaimTypes.NameIdentifier, clientId),
                    new Claim("client_id", clientId),
                    new Claim("cert_thumbprint", cert.Thumbprint),
                    new Claim("not_after", cert.NotAfter.ToUniversalTime().ToString("O"))
                };

                context.Principal = new ClaimsPrincipal(
                    new ClaimsIdentity(claims, CertificateAuthenticationDefaults.AuthenticationScheme));
                context.Success();
                return Task.CompletedTask;
            }
        };
    });

builder.Services.AddAuthorization();

var app = builder.Build();

app.UseAuthentication();
app.UseAuthorization();

app.MapGet("/invoices", (ClaimsPrincipal user) =>
    {
        var clientId = user.FindFirstValue("client_id")
            ?? user.FindFirstValue(ClaimTypes.NameIdentifier);

        return Results.Ok(new
        {
            clientId,
            invoices = new[]
            {
                new { id = "INV-1001", amount = 1200.00m, currency = "PLN" },
                new { id = "INV-1002", amount = 450.50m, currency = "PLN" }
            }
        });
    })
    // RequireAuthorization: endpoint needs the authenticated principal (cert info in User / context).
    // mTLS itself is already required for the whole API by Kestrel above.
    .RequireAuthorization();

app.MapGet("/mtls/check", (ClaimsPrincipal user) =>
    {
        var clientId = user.FindFirstValue("client_id")
            ?? user.FindFirstValue(ClaimTypes.NameIdentifier);
        var thumbprint = user.FindFirstValue("cert_thumbprint");
        var notAfterRaw = user.FindFirstValue("not_after");

        DateTimeOffset? notAfter = DateTimeOffset.TryParse(notAfterRaw, out var parsed)
            ? parsed
            : null;

        return Results.Ok(new
        {
            clientId,
            thumbprint,
            notAfter
        });
    })
    // Same as /invoices: use cert-derived claims from the request context.
    .RequireAuthorization();

app.Run();